#include <mutex>

class MyThreadsafeClass {
private:
  std::recursive_mutex myMutex;
  int myData;
public:
  void increment() {
    myMutex.lock();
    myData++;
    myMutex.unlock();
  }
  int getData() {
    myMutex.lock();
    int temp = myData;
    myMutex.unlock();
    return temp;
  }
  void recursiveOperation() {
    myMutex.lock(); // First acquire
    // ... some code that might recursively call this function ...
    recursiveOperation(); // Recursive call
    // ... more code ...
    myMutex.unlock(); // Release (must match lock calls)
  }
};
